# U14: readability pass, one line-icon set, Month-end close and Follow-ups layout, no orange anywhere (noorange.css,
# generated by dev/tools/gen_noorange.py), and the typography system: the Home's type style on every page, one size up
# (themes/type/ink.css generated, themes/type/base.css, themes/type/t00-current.css; <html data-ty="current">).
import os
from patchlib import P, S
HERE = os.path.dirname(__file__)
TYPE = os.path.join(HERE, '..', '..', 'themes', 'type')
def rd(n): return open(os.path.join(HERE, n), encoding='utf-8').read()
def rt(n): return open(os.path.join(TYPE, n), encoding='utf-8').read()
P("function renderSidebarForViewAsRole(){", rd('polish.js') + "\nfunction renderSidebarForViewAsRole(){")
P('<html lang="en">', '<html lang="en" data-ty="current">')
t = S['text']; i = t.rindex('  .settings-card:empty{display:none;}')
S['text'] = t[:i] + rd('polish.css') + rd('noorange.css') + '\n  /* ===== Typography: Home style on every page ===== */\n' + rt('ink.css') + rt('base.css') + rt('t00-current.css') + t[i:]
